import { createFeed } from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createEffect, createSignal, For, onCleanup, onSettled, Show } from "solid-js";

import { t } from "./theme.ts" with { type: "cssints" };

/** One article of the feed: the words, and the picture a page puts beside them. */
export interface FeedArticle {
  /** Identity of the article: the list's key, and what a page's data is matched by. */
  readonly id: string;
  /** The heading, which names the article for a reader. */
  readonly title: string;
  /** Who wrote it and when, one line: "Rae Molina · 4 March". */
  readonly byline: string;
  /** The summary the article is described by. */
  readonly excerpt: string;
  /** The picture beside the words; decorative, so it carries no text of its own. */
  readonly thumbnail?: JSX.Element | undefined;
}

export interface FeedProps {
  /**
   * The whole list the page has, in reading order. Its length is read once, when the primitive is created: a page that
   * appends to it for good makes a new feed, while more articles of the same list arrive through `loadMore`.
   */
  readonly articles: ReadonlyArray<FeedArticle>;
  /** The feed's accessible name; ignored while `labelledBy` names it. @default "Articles" */
  readonly label?: string | undefined;
  /** The id of the heading that names the feed, when the page has one in sight. */
  readonly labelledBy?: string | undefined;
  /** How many articles are shown before the first load. @default 3 */
  readonly initial?: number | undefined;
  /**
   * Loads the next batch: resolve with how many articles arrived (0 says there are no more). The skin brackets the
   * promise with the primitive's `aria-busy`, and a rejection is announced instead of leaving the sentinel spinning.
   */
  readonly loadMore: (loaded: number) => Promise<number>;
  /** The line under the feed; left out, the keys and the announcement in one sentence. */
  readonly hint?: string | undefined;
  readonly class?: string | undefined;
}

const DEFAULT_HINT =
  "Page Down and Page Up move the focus between articles; when the end of the list comes into view the next ones arrive, and a status line says how many.";

const rootClass = css.cn(css.display("grid"), css.gap(t.space._2));

// The scrollport is the skin's: a feed is a list that grows at its end, and the sentinel at the end is what asks for
// more. The border and the radius are the kit's, and the dark mode moves the tokens underneath.
const paneClass = css.cn(
  css.maxHeight("26.25rem"),
  css.overflowY("auto"),
  css.overflowX("hidden"),
  // the scrollbar appears with the first batch and does not move the cards when it does
  css.scrollbarGutter("stable"),
  css.overscrollBehavior("contain"),
  css.padding(t.space._3),
  css.boxSizing("border-box"),
  css.bg(t.color.page),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.xl),
  css.color(t.color.text),
  css.fontSize(t.font.size),
);

// The feed itself is inside the scrollport and holds only articles; the focusable sentinels sit before and after it.
const feedClass = css.cn(css.display("flex"), css.flexDirection("column"), css.gap(t.space._2));

const cardClass = css.cn(
  css.display("grid"),
  css.gridTemplateColumns("auto minmax(0, 1fr)"),
  css.alignItems("start"),
  css.gap(t.space._3),
  css.padding(t.space._3),
  css.bg(t.color.surface),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.lg),
  css.outline("none"),
  css.hover(css.borderColor(t.color.borderHover)),
  // the primitive keeps the article focusable, and the ring is the one every card of the kit paints
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
);

// A 3:2 picture: the crop is the skin's, so a portrait or a wide one keeps the card's shape.
const thumbnailClass = css.cn(
  css.width("6rem"),
  css.aspectRatio("3 / 2"),
  css.flexShrink("0"),
  css.overflow("hidden"),
  css.borderRadius(t.radius.md),
  css.bg(t.color.buttonBackground),
);

const thumbnailFallbackClass = css.cn(
  css.display("flex"),
  css.alignItems("center"),
  css.justifyContent("center"),
  css.height("100%"),
  css.color(t.color.muted),
  css.fontWeight("600"),
);

const bodyClass = css.cn(css.display("grid"), css.gap(t.space._1), css.minWidth("0"));

const titleClass = css.cn(
  css.margin("0"),
  css.fontSize(t.font.sizeLg),
  css.fontWeight("600"),
  css.lineHeight(1.3),
);

const bylineClass = css.cn(css.margin("0"), css.fontSize(t.font.sizeSm), css.color(t.color.muted));

const excerptClass = css.cn(
  css.margin("0"),
  css.fontSize(t.font.size),
  css.lineHeight(1.5),
  css.color(t.color.muted),
);

// The sentinel at the end of the list: it is the focusable element after the feed (Control+End lands on it) and the line
// that asks for the next batch when the scrollport reaches it.
const sentinelClass = css.cn(
  css.display("flex"),
  css.alignItems("center"),
  css.justifyContent("center"),
  css.gap(t.space._2),
  css.minHeight(t.space._9),
  css.margin("0"),
  css.padding(t.space._2),
  css.fontSize(t.font.sizeSm),
  css.color(t.color.muted),
  css.outline("none"),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("-2px")),
);

// Nothing to look at, still in the tab order: the element before the feed is where Control+Home goes, and focusing it
// scrolls the pane back to the start.
const silentClass = css.cn(
  css.display("block"),
  css.width("1px"),
  css.height("1px"),
  css.overflow("hidden"),
  css.clipPath("inset(50%)"),
  css.whiteSpace("nowrap"),
);

const spin = css.keyframes({ to: css.transform("rotate(1turn)") });

// The spinner is motion, so it turns only for a reader who allows it; with less motion the ring stands still beside the
// words, and the words are what says "loading".
const spinnerClass = css.cn(
  css.width(t.space._3),
  css.height(t.space._3),
  css.flexShrink("0"),
  css.borderRadius("999px"),
  css.border("2px solid", t.color.border),
  css.borderTopColor(t.color.text),
  css.media("(prefers-reduced-motion: no-preference)")(
    css.animation(spin, "0.9s", "linear", "infinite"),
  ),
);

const statusClass = css.cn(
  css.margin("0"),
  css.padding("0", t.space._1),
  css.fontSize(t.font.sizeSm),
  css.color(t.color.muted),
);

const hintClass = css.cn(
  css.margin("0"),
  css.padding("0", t.space._1),
  css.fontSize(t.font.sizeSm),
  css.color(t.color.muted),
);

/** `1 article` / `3 articles`, so the status line reads as a sentence. */
const plural = (count: number): string => `${count} ${count === 1 ? "article" : "articles"}`;

/**
 * APG feed, styled: `createFeed` owns the loaded count, the `aria-posinset` / `aria-setsize` of each article, the one tab
 * stop per article, the Page Up / Page Down and Control+Home / Control+End keys, the focus on the article the reading
 * cursor is at, and `aria-busy` while a batch is in flight. The skin owns the scrollport, the cards (surface, border,
 * radius and the theme's tokens in light and dark), the thumbnail's 3:2 crop, the loading sentinel and its spinner, the
 * status line, and the `prefers-reduced-motion` rule the spinner reads.
 *
 * The sentinel is both of the ends the primitive names: it is the focusable element after the feed, and an
 * `IntersectionObserver` asks for the next batch when the scrollport brings it into view. A batch that arrives while the
 * sentinel holds the focus moves the focus to the first of the new articles, so the reader never loses their place.
 */
export const Feed = (props: FeedProps): JSX.Element => {
  const total = props.articles.length;
  const feed = createFeed({
    items: total,
    totalArticles: total,
    defaultValue: props.initial ?? 3,
    get labelledBy() {
      return props.labelledBy;
    },
  });

  const hasMore = (): boolean => feed.loaded() < total;
  const [failed, setFailed] = createSignal(false);

  let pane: HTMLDivElement | undefined;
  let before: HTMLSpanElement | undefined;
  let after: HTMLDivElement | undefined;
  let observer: IntersectionObserver | undefined;
  let disposed = false;
  onCleanup(() => {
    disposed = true;
    observer?.disconnect();
  });

  /** Focus the article at a posinset, or the sentinel on either side the primitive moved the cursor to. */
  const focusActive = (active: number | "before" | "after"): void => {
    if (typeof active === "string") {
      // the sentinels are only taken when the key came from inside the feed: mounting must not steal the page's focus
      if (pane === undefined || !pane.contains(document.activeElement)) {
        return;
      }
      (active === "before" ? before : after)?.focus();
      return;
    }
    const element = pane?.querySelector<HTMLElement>(`[data-posinset="${active}"]`);
    if (element !== undefined && element !== null && element !== document.activeElement) {
      element.focus();
    }
  };

  createEffect(
    () => feed.active(),
    (active) => focusActive(active),
  );

  // An arriving batch is the page's: the primitive only says that one is wanted.
  createEffect(
    () => feed.busy(),
    (busy) => {
      if (!busy) {
        return;
      }
      const loadedBefore = feed.loaded();
      const hadFocus = after !== undefined && document.activeElement === after;
      void (async () => {
        try {
          const arrived = await props.loadMore(loadedBefore);
          if (disposed) {
            return;
          }
          setFailed(false);
          feed.loadFinish(arrived);
          // the sentinel is gone when the last batch lands, so the focus goes to the first article that came in
          if (hadFocus && feed.loaded() > loadedBefore) {
            queueMicrotask(() => {
              if (!disposed) {
                focusActive(loadedBefore + 1);
              }
            });
          }
        } catch {
          if (!disposed) {
            feed.loadFail();
            setFailed(true);
          }
        }
      })();
    },
  );

  // The sentinel asks for a batch when the scrollport reaches it; the primitive ignores the request when one is in
  // flight or the whole list is already loaded.
  onSettled(() => {
    if (typeof IntersectionObserver === "undefined") {
      return;
    }
    observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          feed.loadStart();
        }
      },
      { root: pane ?? null, rootMargin: "0px 0px 48px 0px" },
    );
    if (after !== undefined) {
      observer.observe(after);
    }
  });

  const status = (): string => {
    if (failed()) {
      return "Could not load more articles.";
    }
    if (feed.busy()) {
      return "Loading more articles…";
    }
    if (!hasMore()) {
      return `All ${plural(total)}.`;
    }
    return `${feed.loaded()} of ${plural(total)}.`;
  };

  return (
    <div data-part="feed-root" class={css.cn(rootClass, props.class)}>
      <div
        data-part="feed-pane"
        class={paneClass}
        ref={(node: HTMLDivElement) => {
          pane = node;
        }}
      >
        <span {...feed.beforeProps} data-part="feed-before" class={silentClass}>
          Start of feed
        </span>
        <div
          {...feed.feedProps}
          data-part="feed"
          aria-label={props.labelledBy === undefined ? (props.label ?? "Articles") : undefined}
          class={feedClass}
        >
          <For each={props.articles.slice(0, feed.loaded())}>
            {(article, index) => {
              const position = index() + 1;
              const own = feed.articleProps(position);
              return (
                <article
                  {...own}
                  data-part="feed-article"
                  data-posinset={position}
                  data-id={article.id}
                  class={cardClass}
                >
                  <div aria-hidden="true" class={thumbnailClass}>
                    <Show
                      when={article.thumbnail}
                      fallback={
                        <span class={thumbnailFallbackClass}>
                          {article.title.slice(0, 1).toUpperCase()}
                        </span>
                      }
                    >
                      {article.thumbnail}
                    </Show>
                  </div>
                  <div class={bodyClass}>
                    <h3 id={own["aria-labelledby"]} class={titleClass}>
                      {article.title}
                    </h3>
                    <p class={bylineClass}>{article.byline}</p>
                    <p id={own["aria-describedby"]} class={excerptClass}>
                      {article.excerpt}
                    </p>
                  </div>
                </article>
              );
            }}
          </For>
        </div>
        <Show when={hasMore() || feed.busy()}>
          <div
            {...feed.afterProps}
            data-part="feed-sentinel"
            class={sentinelClass}
            ref={(node: HTMLDivElement) => {
              after = node;
            }}
          >
            <Show when={feed.busy()} fallback={<span>More articles below</span>}>
              <span aria-hidden="true" data-part="feed-spinner" class={spinnerClass} />
              <span>Loading more…</span>
            </Show>
          </div>
        </Show>
      </div>
      <p data-part="feed-status" role="status" class={statusClass}>
        {status()}
      </p>
      <p data-part="feed-hint" class={hintClass}>
        {props.hint ?? DEFAULT_HINT}
      </p>
    </div>
  );
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { render } from "@solidjs/web";
import type { JSX } from "@solidjs/web";

import { Feed, type FeedArticle, type FeedProps } from "./feed.tsx";

/** One article of the demo, before its picture is drawn: the words, and the two ends of its cover. */
interface FeedArticleSeed {
  readonly id: string;
  readonly title: string;
  readonly byline: string;
  readonly excerpt: string;
  readonly from: string;
  readonly to: string;
}

/**
 * The demo's journal: six articles at mount and three more that arrive in one batch, so the sentinel has something honest
 * to wait for and then goes away. The covers are drawn, not fetched: the example needs no network and no image files.
 */
export const FEED_ARTICLES: ReadonlyArray<FeedArticleSeed> = [
  {
    id: "feed-quiet-design",
    title: "The quiet cost of a design system",
    byline: "Rae Molina · 4 March",
    excerpt:
      "Every component you add to a kit is a promise to keep it working. The teams that win are the ones that say no.",
    from: "#f3d9c6",
    to: "#d98e63",
  },
  {
    id: "feed-focus",
    title: "Focus is a place, not a state",
    byline: "Ivo Petrović · 2 March",
    excerpt:
      "A focus ring says where the keyboard is. A feed says where the reader is: those are two different maps, and both have to be drawn.",
    from: "#c9dbe8",
    to: "#6d9dc0",
  },
  {
    id: "feed-tokens",
    title: "Tokens are a contract with the dark",
    byline: "Mira Okafor · 27 February",
    excerpt:
      "The palette that reads well on paper turns to mud at night. Derive the dark mode from the same scale and the two cannot drift.",
    from: "#d5cfdf",
    to: "#8b7aa8",
  },
  {
    id: "feed-scroll",
    title: "Infinite scroll needs an end",
    byline: "Rae Molina · 24 February",
    excerpt:
      "A list that never ends has no landmark, no footer and no way back. A feed should say how much is left, and then stop.",
    from: "#cfe0cd",
    to: "#7ba382",
  },
  {
    id: "feed-pictures",
    title: "Pictures that keep their shape",
    byline: "Noor Haddad · 20 February",
    excerpt:
      "An aspect ratio on the frame is worth more than a rule about image sizes: the crop is the layout's, not the photograph's.",
    from: "#f0dfb8",
    to: "#b99a4f",
  },
  {
    id: "feed-words",
    title: "Write the sentence before the component",
    byline: "Ivo Petrović · 18 February",
    excerpt:
      "If you cannot say what the widget does in one line, the reader will not find out either. Start with the line, then build it.",
    from: "#e6c6c0",
    to: "#b06a63",
  },
  {
    id: "feed-status",
    title: "The status line nobody reads",
    byline: "Mira Okafor · 15 February",
    excerpt:
      "A polite live region is not decoration: it is the only way a screen reader learns that three more articles arrived.",
    from: "#c8d8d4",
    to: "#6a9b92",
  },
  {
    id: "feed-motion",
    title: "Motion is a preference",
    byline: "Noor Haddad · 12 February",
    excerpt:
      "A spinner that turns for everyone turns against the reader who asked it not to. The preference is one line, and it is theirs.",
    from: "#d8d0c2",
    to: "#9b8c76",
  },
  {
    id: "feed-end",
    title: "Every feed ends somewhere",
    byline: "Rae Molina · 9 February",
    excerpt:
      "The last batch is the point of the exercise: say that the list is complete, and take the loading line away.",
    from: "#cdd3e4",
    to: "#7f88ab",
  },
];

/** The articles shown before the first batch: the first six of the list. */
export const FEED_INITIAL = 6;

/** How many articles a batch brings. */
export const FEED_BATCH = 3;

/** How long the demo's loader takes: the spinner is visible for this long, and the test waits it out. */
export const FEED_LOAD_DELAY = 180;

/** A cover for one seed: a drawn gradient, so the demo fetches nothing. */
const cover = (seed: FeedArticleSeed): JSX.Element => (
  <div
    aria-hidden="true"
    style={{
      width: "100%",
      height: "100%",
      background: `linear-gradient(135deg, ${seed.from}, ${seed.to})`,
    }}
  />
);

/** The seeds as the skin's articles; the test and the page read the same list. */
export const buildFeedArticles = (): ReadonlyArray<FeedArticle> =>
  FEED_ARTICLES.map((seed) => ({
    id: seed.id,
    title: seed.title,
    byline: seed.byline,
    excerpt: seed.excerpt,
    thumbnail: cover(seed),
  }));

const wait = (ms: number): Promise<void> =>
  new Promise((resolve) => {
    setTimeout(resolve, ms);
  });

/**
 * The demo's loader: it waits, then hands over the next three of the same local list. No network, and no surprise: the
 * delay is the fixture's, and the count is what is actually left.
 */
export const demoLoadMore = async (loaded: number): Promise<number> => {
  await wait(FEED_LOAD_DELAY);
  return Math.min(FEED_BATCH, FEED_ARTICLES.length - loaded);
};

export interface FeedExampleProps {
  readonly class?: string | undefined;
  /** A test passes its own loader to count the requests; the demo's own waits and returns the rest of the list. */
  readonly loadMore?: FeedProps["loadMore"] | undefined;
}

/**
 * The starter in ordinary use: a journal of articles in a 360 px scrollport, six to begin with, three more when the end
 * of the list scrolls into view, and the sentence that says how the keyboard and the status line behave. A page copies
 * this and swaps `FEED_ARTICLES` for its own data and `demoLoadMore` for its fetch.
 */
export const FeedExample = (props: FeedExampleProps): JSX.Element => (
  <Feed
    class={props.class}
    articles={buildFeedArticles()}
    initial={FEED_INITIAL}
    label="Studio notes"
    loadMore={props.loadMore ?? demoLoadMore}
  />
);

/** What a mounted demo hands the test: the scrollport, the counts each loader call saw, and a teardown. */
export interface MountedFeed {
  readonly root: HTMLElement;
  /** The scroll container: scrolling it to the end brings the sentinel into view. */
  readonly pane: HTMLElement;
  /** How many articles each loader call was asked for. */
  readonly runs: number[];
  readonly dispose: () => void;
}

/** The demo's width, so the cards have the same room in every test run. */
const DEMO_WIDTH = 360;

/**
 * Mounts the styled feed in ordinary use at a 360 px scrollport. The primitive owns the loaded count, the article
 * semantics and the keys; the fixture is the page's content and its loader.
 */
export const mountFeed = (): MountedFeed => {
  const root = document.createElement("div");
  root.style.width = `${DEMO_WIDTH}px`;
  document.body.append(root);
  const runs: number[] = [];
  const dispose = render(
    () => (
      <FeedExample
        loadMore={async (loaded) => {
          runs.push(loaded);
          return demoLoadMore(loaded);
        }}
      />
    ),
    root,
  );
  const pane = root.querySelector<HTMLElement>('[data-part="feed-pane"]');
  if (pane === null) {
    throw new Error("feed fixture: the scrollport was not mounted");
  }
  return {
    root,
    pane,
    runs,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

import { afterEach, describe, expect, it } from "vite-plus/test";

import { FEED_ARTICLES, type MountedFeed, mountFeed } from "./feed.fixture";

// @cssints/headless checks `createFeed` against specs/apg/feed.qnt and the ported APG scenarios. This file is the skin's
// oracle: it mounts the starter in a real Chromium and scrolls the same pane a reader does. The skin's own parts (the
// scrollport, the cards, the sentinel and its spinner, the status line and the focus that follows the primitive's
// cursor) are only observable through the DOM.
//
// The fixture's pane is 360 px wide and the skin caps it at 420 px tall, so the sentinel starts below the fold and the
// loader's 180 ms delay is long enough to see `aria-busy` and the spinner.

/** Solid applies setters on the next flush, and an IntersectionObserver callback lands after a frame: two frames settle. */
const frame = (): Promise<void> =>
  new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve())));

/** Polls until `done` holds, so the fixture's delay is waited for rather than assumed. */
const waitFor = async (done: () => boolean, limit = 5000): Promise<void> => {
  const start = performance.now();
  while (!done()) {
    if (performance.now() - start > limit) {
      throw new Error("waitFor timed out");
    }
    await frame();
  }
};

const live: MountedFeed[] = [];

const mounted = (): MountedFeed => {
  const instance = mountFeed();
  live.push(instance);
  return instance;
};

afterEach(() => {
  for (const instance of live.splice(0)) {
    instance.dispose();
  }
});

const required = <T extends Element>(parent: ParentNode, selector: string): T => {
  const element = parent.querySelector<T>(selector);
  if (element === null) {
    throw new Error(`feed: no ${selector}`);
  }
  return element;
};

const feed = (root: ParentNode): HTMLElement => required(root, '[role="feed"]');

const articles = (root: ParentNode): HTMLElement[] => [
  ...root.querySelectorAll<HTMLElement>('[data-part="feed-article"]'),
];

const sentinel = (root: ParentNode): HTMLElement | null =>
  root.querySelector<HTMLElement>('[data-part="feed-sentinel"]');

const status = (root: ParentNode): HTMLElement => required(root, '[data-part="feed-status"]');

const spinner = (root: ParentNode): HTMLElement | null =>
  root.querySelector<HTMLElement>('[data-part="feed-spinner"]');

/** A key on the focused element, as a reader's would arrive. */
const press = async (target: HTMLElement, key: string, ctrlKey = false): Promise<void> => {
  target.dispatchEvent(
    new KeyboardEvent("keydown", { key, ctrlKey, bubbles: true, cancelable: true }),
  );
  await frame();
};

describe("Feed", () => {
  it("is a named feed whose articles carry the primitive's position and size", () => {
    const { root } = mounted();

    expect(feed(root).getAttribute("aria-label")).toBe("Studio notes");
    // the primitive brackets a load; nothing is in flight at mount
    expect(feed(root).hasAttribute("aria-busy")).toBe(false);

    const cards = articles(root);
    expect(cards).toHaveLength(6);
    expect(cards.map((card) => card.getAttribute("role"))).toEqual(
      Array.from({ length: 6 }, () => "article"),
    );
    expect(cards.map((card) => card.getAttribute("aria-posinset"))).toEqual([
      "1",
      "2",
      "3",
      "4",
      "5",
      "6",
    ]);
    expect(cards.map((card) => card.getAttribute("aria-setsize"))).toEqual(
      Array.from({ length: 6 }, () => "6"),
    );
    expect(cards.every((card) => card.tabIndex === 0)).toBe(true);

    // the title and the summary the primitive points at are the ones the page wrote
    const first = cards[0] as HTMLElement;
    expect(document.getElementById(first.getAttribute("aria-labelledby") ?? "")?.textContent).toBe(
      FEED_ARTICLES[0]?.title,
    );
    expect(document.getElementById(first.getAttribute("aria-describedby") ?? "")?.textContent).toBe(
      FEED_ARTICLES[0]?.excerpt,
    );
  });

  it("keeps every id and every key of the feed distinct", () => {
    const { root } = mounted();

    const ids = [...root.querySelectorAll<HTMLElement>("[id]")].map((element) => element.id);
    expect(new Set(ids).size).toBe(ids.length);

    const keys = articles(root).map((card) => card.dataset["id"]);
    expect(new Set(keys).size).toBe(keys.length);
    expect(keys).toEqual(FEED_ARTICLES.slice(0, 6).map((article) => article.id));
  });

  it("loads the next three when the sentinel scrolls into view, and says so", async () => {
    const instance = mounted();
    const { root, pane } = instance;

    expect(status(root).textContent).toBe("6 of 9 articles.");
    const stop = sentinel(root);
    expect(stop?.textContent?.trim()).toBe("More articles below");
    // below the fold: nothing loads until the reader gets there
    const paneBox = pane.getBoundingClientRect();
    expect((stop as HTMLElement).getBoundingClientRect().top).toBeGreaterThanOrEqual(
      paneBox.top + pane.clientHeight,
    );
    expect(instance.runs).toEqual([]);

    pane.scrollTop = pane.scrollHeight;
    await waitFor(() => feed(root).getAttribute("aria-busy") === "true");
    // the spinner and the line are the skin's, while the primitive owns the busy state
    expect(spinner(root)).not.toBeNull();
    expect(status(root).textContent).toBe("Loading more articles…");

    await waitFor(() => articles(root).length === 9);
    expect(instance.runs).toEqual([6]);
    expect(feed(root).hasAttribute("aria-busy")).toBe(false);

    // the batch is counted, announced and positioned by the primitive
    expect(status(root).textContent).toBe("All 9 articles.");
    expect(articles(root).map((card) => card.getAttribute("aria-posinset"))).toEqual(
      Array.from({ length: 9 }, (_, at) => `${at + 1}`),
    );
    expect(articles(root)[8]?.getAttribute("aria-setsize")).toBe("9");
    // the last batch removes the sentinel: there is nothing left to ask for
    expect(sentinel(root)).toBeNull();
    expect(pane.scrollHeight).toBeGreaterThan(pane.clientHeight);
  });

  it("moves the focus between articles with Page Down and Page Up", async () => {
    const { root } = mounted();
    const first = articles(root)[0] as HTMLElement;
    first.focus();
    await frame();
    expect(document.activeElement).toBe(first);

    await press(first, "PageDown");
    expect(document.activeElement).toBe(articles(root)[1]);
    await press(document.activeElement as HTMLElement, "PageDown");
    expect(document.activeElement).toBe(articles(root)[2]);
    await press(document.activeElement as HTMLElement, "PageUp");
    expect(document.activeElement).toBe(articles(root)[1]);
  });

  it("leaves the feed at Control+End onto the sentinel, and keeps the focus when the batch lands", async () => {
    const { root } = mounted();
    const first = articles(root)[0] as HTMLElement;
    first.focus();
    await frame();

    await press(first, "End", true);
    const stop = sentinel(root);
    expect(document.activeElement).toBe(stop);

    // focusing the sentinel scrolls it into view, so the batch arrives; the sentinel then goes away, and the focus moves
    // to the first article that came in rather than back to the page
    await waitFor(() => articles(root).length === 9);
    await waitFor(() => document.activeElement === articles(root)[6]);
    expect(sentinel(root)).toBeNull();
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
